rogramming","level":"Intermediate","hours":1.12,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Datacenter integration for Azure Stack Hub","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/datacenter-integration-azure-stack-hub/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-d733932c663aaa1f","version":"2026-10-21T17:02:00+00:00","title":"Explore Azure for SAP databases","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":4.33,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"This module explores SAP on Azure database support and best practices for Azure for SAP workloads. Prepare for Exam AZ-120 Planning and Administering Microsoft Azure for SAP Workloads.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/explore-azure-databases/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-b0c6cd4b71256494","version":"2026-10-21T17:02:00+00:00","title":"Guided project: Monitor Azure with Service Health and Activity Log alerts","provider":"Microsoft Learn","category":"Programming","level":"Beginner","hours":0.6,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Set up proactive monitoring with Service Health alerts and Activity Log alerts without paid compute resources.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/guided-project-monitor-service-health-activity-alerts/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-3e943b0196da1ccf","version":"2026-10-21T17:02:00+00:00","title":"Monitor and report on security events