":"https://learn.microsoft.com/en-us/training/modules/develop-speech-agent-speech-mcp/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-d8ebe7910c507326","version":"2026-10-21T17:02:00+00:00","title":"Enhance your LinkedIn profile with Microsoft Copilot and ace your interview","provider":"Microsoft Learn","category":"Programming","level":"Beginner","hours":1.32,"skills":["AI Tools"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Your LinkedIn profile is a gateway to networking, career growth, and personal branding. By leveraging Microsoft Copilot, you can refine your headline, summary, and experience sections, ensuring that your profile highlights your strengths and potential, in addition to serving as a valuable interview preparation tool.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/enhance-linkedin-profile-with-copilot-ace-your-interview/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-02c36defdb47cbeb","version":"2026-10-21T17:02:00+00:00","title":"Create and manage session host image for Azure Virtual Desktop","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":0.88,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"A Shared Image Gallery simplifies custom image sharing across your organization. Custom images can be used to bootstrap deployment tasks like preloading applications, application configurations, and other OS configurations.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/create-manage-session-host-image/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-c0a255a150d229df","version":"2026-10-21T17:02:00+00:00","title":"Design a dream destination using Microsoft Copilot","provider":"Microsoft Learn","category":"Programming","level":"Beginner","hours":0.88,"skills":["AI Tools"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Interact with Microsoft Copilot to learn about the capabilities of generative AI. Bring your personal creativity and passion to dream up a novel destination and create the content to help tell its story. Use Microsoft Copilot to ideate, research, and generate content. Use tips and techniques to write good prompts. Apply format and tone.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/design-dream-destination-ai-copilot/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-1d584366e9963521","version":"2026-10-21T17:02:00+00:00","title":"Understand hybrid data platform on SQL Server 2025","provider":"Microsoft Learn","category":"Programming","level":"Beginner","hours":0.97,"skills":["SQL"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"This module helps users understand the hybrid data platform capabilities of SQL Server 2025.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/understand-hybrid-data-platform-sql-server/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-1905474f4c70b100","version":"2026-10-21T17:02:00+00:00","title":"Optimize costs by using Azure Hybrid Benefit","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":1.2,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Microsoft Azure offers Azure Hybrid Benefit, which helps organizations reduce costs when migrating to the cloud environment. You can leverage several Azure discounts and combine them with other services and strategic pricing offerings.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/optimize-costs-using-azure-hybrid-benefit/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-f0d8772cb651ab8d","version":"2026-10-21T17:02:00+00:00","title":"Migrate Oracle workloads to Azure IaaS virtual machines","provider":"Microsoft Learn","category":"Programming","level":"Beginner","hours":0.43,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Learn how you can migrate your Oracle workloads to Azure IaaS virtual machines.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/oracle-workload-azure-iaas/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-adc44418c0268102","version":"2026-10-21T17:02:00+00:00","title":"Design solutions that align with the Microsoft Cybersecurity Reference Architecture (MCRA) and Microsoft cloud security benchmark (MCSB)","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":1.12,"skills":["Cloud Computing","Cybersecurity"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"You learn about the Microsoft Cybersecurity Reference Architecture (MCRA) and Microsoft Cloud Security Benchmark (MCSB) and how you can use them to design more secure solutions.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/design-solutions-microsoft-cybersecurity-cloud-security-benchmark/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-8c03c6798e38bc63","version":"2026-10-21T17:02:00+00:00","title":"Configure SIEM security operations using Microsoft Sentinel","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":1.5,"skills":["Cybersecurity"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Configure security information and event management (SIEM) security operations using Microsoft Sentinel.","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/configure-siem-security-operations-using-microsoft-sentinel/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-27cb485b3067db2a","version":"2026-10-21T17:02:00+00:00","title":"Develop secure IoT solutions for Azure Sphere, Azure RTOS and Azure IoT Central","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":2.0,"skills":["Cloud Computing","Cybersecurity"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Develop highly secure IoT solutions with Azure Sphere, Azure RTOS and Azure IoT Central","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/develop-secure-iot-solutions-azure-sphere-iot-central/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-c9255164bae2e8ce","version":"2026-10-21T17:02:00+00:00","title":"Connect Power Platform to SAP on Azure","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours":0.55,"skills":["Cloud Computing"],"cost":0,"rating":0,"learners":0,"online":true,"delivery":"online","setting":"indoor","hrdc":false,"instructor":"Microsoft Learn","hue":210,"description":"Connect Power Platform to SAP on Azure","resourceUrl":"https://learn.microsoft.com/en-us/training/modules/connect-power-platform-to-sap-azure/?WT.mc_id=api_CatalogApi","sourceType":"provider-catalogue"},{"id":"mslearn-010e4159ca51b092","version":"2026-10-21T17:02:00+00:00","title":"Optimize query performance using indexes in Azure DocumentDB","provider":"Microsoft Learn","category":"Programming","level":"Intermediate","hours"